            return funcao.apply(a, b);
        }

        public String getSimbolo() {
            return simbolo;
        }

        public static Optional<BinOp> from(String s) {
            return Arrays.stream(values())
                    .filter(o -> o.simbolo.equals(s))
                    .findFirst();
        }
    }

    private enum UnOp {
        RAIZ("sqrt", a -> {
            if (a.compareTo(BigDecimal.ZERO) < 0) {
                throw new ArithmeticException("Raiz quadrada de número negativo.");
            }
            return new BigDecimal(Math.sqrt(a.doubleValue()), MC);
        }),
        FATORIAL("fact", a -> {
            if (a.compareTo(BigDecimal.ZERO) < 0 || a.stripTrailingZeros().scale() > 0) {
                throw new IllegalArgumentException("Fatorial apenas para inteiros não-negativos.");
            }
            int n = a.intValueExact();
            BigDecimal res = BigDecimal.ONE;
            for (int i = 2; i <= n; i++) {
                res = res.multiply(BigDecimal.valueOf(i), MC);
            }
            return res;
        });

        private final String simbolo;
        private final UnaryOperator<BigDecimal> funcao;

        UnOp(String simbolo, UnaryOperator<BigDecimal> funcao) {
            this.simbolo = simbolo;
            this.funcao = funcao;
        }

        public BigDecimal aplicar(BigDecimal a) {
            return funcao.apply(a);
        }

        public String getSimbolo() {
            return simbolo;
        }

        public static Optional<UnOp> from(String s) {
            return Arrays.stream(values())
                    .filter(o -> o.simbolo.equalsIgnoreCase(s))
                    .findFirst();
        }
    }

    public static void main(String[] args) {
        new CalculadoraCompleta().iniciar();
    }

    public void iniciar() {
        System.out.println("=== Calculadora Completa Java ===");
        System.out.println("Formatos aceitos: <num> <op> <num> (ex: 5 + 3) ou <op> <num> (ex: sqrt 9)");
        System.out.println("Comandos: history, clear, exit\n");

        while (true) {
            System.out.print("> ");
            String linha = SC.nextLine().trim();

            if (linha.equalsIgnoreCase("exit")) {
                System.out.println("Encerrando...");
                break;
            }
            if (linha.equalsIgnoreCase("history")) {
                exibirHistorico();
                continue;
            }
            if (linha.equalsIgnoreCase("clear")) {
                historico.clear();
                System.out.println("Histórico limpo.");
                continue;
            }
            if (linha.isEmpty()) {
                continue;
            }

            try {
                String[] partes = linha.split("\\s+");
                BigDecimal resultado;
                String registro;

                if (partes.length == 2) {
                    UnOp opUnaria = UnOp.from(partes[0])
                            .orElseThrow(() -> new IllegalArgumentException("Operação unária desconhecida."));
                    BigDecimal valor = new BigDecimal(partes[1], MC);
                    resultado = opUnaria.aplicar(valor);
                    registro = String.format("%s %s = %s", opUnaria.getSimbolo(), valor, resultado);
                } else if (partes.length == 3) {
                    BigDecimal a = new BigDecimal(partes[0], MC);
                    BinOp opBinaria = BinOp.from(partes[1])
                            .orElseThrow(() -> new IllegalArgumentException("Operação binária desconhecida."));
                    BigDecimal b = new BigDecimal(partes[2], MC);
                    resultado = opBinaria.aplicar(a, b);
                    registro = String.format("%s %s %s = %s", a, opBinaria.getSimbolo(), b, resultado);
                } else {
                    throw new IllegalArgumentException("Formato inválido. Use: <num> <op> <num> ou <op> <num>.");
                }

                System.out.println("Resultado: " + resultado.stripTrailingZeros().toPlainString());
                historico.add(registro);

            } catch (Exception e) {
                System.out.println("Erro: " + e.getMessage());
            }
        }
    }

    private void exibirHistorico() {
        System.out.println("\n--- Histórico ---");
        if (historico.isEmpty()) {
            System.out.println("Nenhuma operação registrada.");
        } else {
            historico.forEach(System.out::println);
        }
        System.out.println("-----------------\n");
    }
}
